 CheckBox smoothingEnabled=new CheckBox{Checked=true};TrackBar vectorWeightSlider,vectorTaperSlider,vectorOpacitySlider;
 void ConfigureSliders(FlowLayoutPanel tools){
  SimplifySlider(tools,size,sizeSlider,"SIZE",1,"px",false);SimplifySlider(tools,opacity,opacitySlider,"OPACITY",1,"%",false);SimplifySlider(tools,flow,flowSlider,"FLOW",1,"%",false);SimplifySlider(tools,hardness,hardnessSlider,"HARDNESS",1,"%",false);
  int brushIndex=tools.Controls.GetChildIndex(sizeSlider)+1;foreach(var slider in new[]{hardnessSlider,opacitySlider,flowSlider}){tools.Controls.SetChildIndex((Control)slider.Tag,brushIndex++);tools.Controls.SetChildIndex(slider,brushIndex++);}
  vectorWeightSlider=MakeVectorSlider(tools,vectorWidth,"WEIGHT / STROKE",25,2000,100,"px");vectorTaperSlider=MakeVectorSlider(tools,vectorTaper,"LINE TAPER",0,100,1,"%");vectorOpacitySlider=MakeVectorSlider(tools,vectorOpacity,"SHAPE OPACITY",0,100,1,"%");AddPolygonSidesSlider(tools);
  int index=tools.Controls.GetChildIndex(smoothingLabel);tools.Controls.Remove(smoothingLabel);smoothingEnabled.Text="SMOOTH · "+smoothingSlider.Value+"%";smoothingEnabled.Size=new Size(170,25);tools.Controls.Add(smoothingEnabled);tools.Controls.SetChildIndex(smoothingEnabled,index);smoothingEnabled.CheckedChanged+=delegate{canvas.EndStroke();smoothingSlider.Enabled=smoothingEnabled.Checked;canvas.Smoothing=smoothingEnabled.Checked?smoothingSlider.Value:0;};smoothingSlider.ValueChanged+=delegate{smoothingEnabled.Text="SMOOTH · "+smoothingSlider.Value+"%";};
 }
 TrackBar MakeVectorSlider(FlowLayoutPanel tools,NumericUpDown number,string name,int min,int max,int scale,string unit){var slider=new TrackBar{Minimum=min,Maximum=max,Value=Math.Max(min,Math.Min(max,(int)(number.Value*scale))),SmallChange=scale==100?25:1,LargeChange=scale==100?100:10};int index=tools.Controls.GetChildIndex(number);tools.Controls.Add(slider);tools.Controls.SetChildIndex(slider,index+1);SimplifySlider(tools,number,slider,name,scale,unit,true);return slider;}
 void SimplifySlider(FlowLayoutPanel tools,NumericUpDown number,TrackBar slider,string name,int scale,string unit,bool vector){int index=tools.Controls.GetChildIndex(number);var label=tools.Controls[index-1] as Label;tools.Controls.Remove(number);if(vector){vectorControls.Remove(number);vectorControls.Add(slider);}slider.AutoSize=false;slider.Size=new Size(170,30);slider.TickStyle=TickStyle.None;slider.Margin=new Padding(3,0,3,3);if(label!=null){slider.Tag=label;label.Size=new Size(170,18);label.Margin=new Padding(3,14,3,0);}bool syncingSlider=false;Action update=delegate{if(label!=null)label.Text=(name=="SHAPE OPACITY"||name=="POLYGON SIDES")?name+" - "+number.Value.ToString("0")+unit:name+" · "+number.Value.ToString(scale==100?"0.##":"0")+" "+unit;};number.ValueChanged+=delegate{syncingSlider=true;slider.Value=Math.Max(slider.Minimum,Math.Min(slider.Maximum,(int)Math.Round(number.Value*scale)));syncingSlider=false;update();};if(vector)slider.ValueChanged+=delegate{if(!syncingSlider)number.Value=(decimal)slider.Value/scale;};update();}
 void AddCurvePointButtons(FlowLayoutPanel tools){addCurvePoint=Theme.Button("Add point   +",delegate{canvas.EditCurvePoint(true);canvas.Focus();});removeCurvePoint=Theme.Button("Remove points   −",delegate{canvas.EditCurvePoint(false);canvas.Focus();});addCurvePoint.Width=removeCurvePoint.Width=170;tools.Controls.Add(addCurvePoint);tools.Controls.Add(removeCurvePoint);tools.Controls.Add(new Label{Text="Shift-click to select points.\nSelect two shape points to add\ntheir midpoint (+).",Width=170,Height=50});canvas.PointSelectionChanged=UpdatePointButtons;UpdatePointButtons();}

}
partial class Canvas {
 public void ChangeVectorOpacity(float opacity){if(Doc!=null&&Doc.Selected.IsLocked)return;if(selectedVector==null||Doc==null||!Doc.Selected.Vectors.Contains(selectedVector)||selectedVector.Opacity==opacity)return;if(BeforeStroke!=null)BeforeStroke();selectedVector.Opacity=opacity;Doc.Selected.InvalidateVectors();if(AfterStroke!=null)AfterStroke();Invalidate();}
 public void EditCurvePoint(bool add){if(Doc!=null&&Doc.Selected.IsLocked)return;if(selectedVector==null||!Doc.Selected.Vectors.Contains(selectedVector))return;if(add?!CanAddCurvePoint:!CanRemoveCurvePoint)return;if(BeforeStroke!=null)BeforeStroke();var indices=selectedPoints.OrderBy(i=>i).ToArray();if(selectedVector.Kind=="Ellipse"){var grips=selectedVector.Grips();selectedVector.Points=new System.Collections.Generic.List<PointF>{grips[0],grips[2],grips[1],grips[3]};selectedVector.Kind="Closed curve";indices=indices.Select(i=>i==1?2:i==2?1:i).OrderBy(i=>i).ToArray();}if(add){var a=selectedVector.Points[indices[0]];var b=selectedVector.Points[indices[1]];int at=indices[0]+1;selectedVector.ShiftHandleIndices(at,true);selectedVector.Points.Insert(at,new PointF((a.X+b.X)/2,(a.Y+b.Y)/2));selectedPoints.Clear();selectedPoints.Add(at);vectorHandle=at;}else{for(int i=indices.Length-1;i>=0;i--){selectedVector.ShiftHandleIndices(indices[i],false);selectedVector.Points.RemoveAt(indices[i]);}selectedPoints.Clear();vectorHandle=-1;}Doc.Selected.InvalidateVectors();if(AfterStroke!=null)AfterStroke();NotifyPointSelection();Invalidate();}

}
